# when an object is part of a reference cycle. Each entry is removed by a
# second reference, whose callback is dict.pop: no Python function either.
_watched = {}
_exiting = False


def watch(obj, handle, destroy):
    """Call destroy(handle) when obj is collected, and return the reference
    that does it.

    ``handle`` is read at that time: a constructor that writes it makes obj the
    owner as soon as the C++ object exists. To cancel, set the reference's
    ``_as_parameter_`` to a NULL handle of the same type. Once the exit
    handlers that were registered after this module was imported have run,
    nothing is destroyed on collection any more (see _leave_alone).
    """
